"""Route path matching and dictionary consolidation."""
from typing import Dict, Any, List

def deep_merge_matchers(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    res = dict(base)
    for k, v in override.items():
        if k in res and isinstance(res[k], dict) and isinstance(v, dict):
            res[k] = deep_merge_matchers(res[k], v)
        else:
            res[k] = v
    return res

def normalize_prefix(path: str) -> str:
    return "/" + path.strip("/")

def extract_headers(matcher_config: Dict[str, Any]) -> List[str]:
    """Extract header names from matcher configuration."""
    headers = matcher_config.get("headers", [])
    if isinstance(headers, list):
        return headers
    return []

def apply_header_matchers(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    """Apply header matchers from override configuration, preserving base headers."""
    result = dict(base)
    base_headers = extract_headers(base)
    override_headers = extract_headers(override)

    # Preserve base headers while applying override headers
    if base_headers:
        result["headers"] = base_headers
    if override_headers:
        result["headers"] = override_headers

    return result
